After the code below, you run `graph.invoke(None, before.config)`. Which nodes execute, and how many snapshots does the thread's history hold afterwards?

```python
class State(TypedDict):
    topic: str
    jokes: Annotated[list[str], operator.add]

def pick_topic(state: State):
    return {"topic": "cats"}

def write_joke(state: State):
    return {"jokes": [f"joke about {state['topic']}"]}

# START -> pick_topic -> write_joke, compiled with InMemorySaver()
config = {"configurable": {"thread_id": "t1"}}
graph.invoke({"topic": "", "jokes": []}, config)
history = list(graph.get_state_history(config))
before = next(s for s in history if s.next == ("write_joke",))
```

After the code below, you fork and resume like this. What is `result`, and what does `graph.get_state(config).values` return afterwards?

```python
class State(TypedDict):
    topic: str
    jokes: Annotated[list[str], operator.add]

def pick_topic(state: State):
    return {"topic": "cats"}

def write_joke(state: State):
    return {"jokes": [f"joke about {state['topic']}"]}

# START -> pick_topic -> write_joke, compiled with InMemorySaver()
config = {"configurable": {"thread_id": "t1"}}
graph.invoke({"topic": "", "jokes": []}, config)
history = list(graph.get_state_history(config))
before = next(s for s in history if s.next == ("write_joke",))

fork_config = graph.update_state(before.config, {"topic": "dogs"})
result = graph.invoke(None, fork_config)
```

`ok` and `flaky` run in the same super-step, and `flaky` fails on the first attempt. What does the final `print` show?

```python
calls = {"ok": 0, "flaky": 0, "after": 0}
FAIL = True

def ok(state):
    calls["ok"] += 1; return {"out": ["ok"]}

def flaky(state):
    calls["flaky"] += 1
    if FAIL: raise RuntimeError("boom")
    return {"out": ["flaky"]}

def after(state):
    calls["after"] += 1; return {"out": ["after"]}

# START -> ok, START -> flaky, [ok, flaky] -> after; InMemorySaver
try:
    graph.invoke({"out": []}, config)
except RuntimeError:
    pass
FAIL = False
graph.invoke(None, config)
print(calls)
```

A subgraph is called inside a parent node. With `checkpointer=True` on the subgraph, the second parent run prints `['seen1', 'seen3']`. What does it print if the subgraph is compiled with plain `compile()` instead?

```python
class M(TypedDict):
    log: Annotated[list[str], operator.add]

def inner(state: M):
    return {"log": [f"seen{len(state['log'])}"]}

sub = StateGraph(M).add_node(inner).add_edge(START, "inner").compile(checkpointer=True)

def call(state: M):
    r = sub.invoke({"log": ["q"]})
    return {"log": [r["log"][-1]]}

graph = (StateGraph(M).add_node(call).add_edge(START, "call")
         .compile(checkpointer=InMemorySaver()))
cfg = {"configurable": {"thread_id": "m"}}
graph.invoke({"log": []}, cfg)
print(graph.invoke({"log": []}, cfg)["log"])
```

An order flow fails in production. What does the `print` show?

```python
class State(TypedDict):
    order: str
    status: str

def validate(state): return {"status": "valid"}
def charge(state): raise RuntimeError("gateway timeout")

# START -> validate -> charge, compiled with a checkpointer
cfg = {"configurable": {"thread_id": "o-1"}}
try:
    graph.invoke({"order": "A1", "status": "new"}, cfg)
except RuntimeError:
    pass
snap = graph.get_state(cfg)
print(snap.values, snap.next, [(t.name, t.error) for t in snap.tasks])
```

